head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vDelCheck = "N";
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.pIndex;
scwin.TR_JOB;
scwin.notiId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
        txb_ISU_CD.setValue(parentWin.txb_SearchIsuCd.getValue());
        txb_ISU_NM.setValue(parentWin.txb_SearchIsuNm.getValue());
        $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo); // 상품정보관리 첨부파일 조회

        await scwin.readSync();
        if (dts_Item.getRowCount() === 0) {
            dts_Item.insertRow();
            btn_save.setBackgroundImage("../img/btn_save.gif");
            btn_save.setDisabled(false);
            btn_Update.setBackgroundImage("../img/btn_modify_d.gif");
            btn_Update.setDisabled(true);
        } else {
            btn_save.setBackgroundImage("../img/btn_save_d.gif");
            btn_save.setDisabled(true);
            btn_Update.setBackgroundImage("../img/btn_modify.gif");
            btn_Update.setDisabled(false);
        }
        edt_EXPS_RTO.focus();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_Update_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Update_onclick = async function() {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = function() {
    try {
        $c.lce.fn_alertMsg('S');
        btn_save.setBackgroundImage("../img/btn_save_d.gif");
        btn_save.setDisabled(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08113.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lce.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name txa_ETN_INVSTWARN_CONTN_OnKillFocus
 * @description txa_ETN_INVSTWARN_CONTN 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.txa_ETN_INVSTWARN_CONTN_OnKillFocus = function() {
    try {
        edt_EXPS_RTO.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08113.txa_ETN_INVSTWARN_CONTN_OnKillFocus" });
    }
};

/**
 * @method
 * @name grd_Fil_OnDblClick
 * @description grd_Fil 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Fil_OnDblClick = function(row, colid) {
    try {
        if (dts_Etn_File.getRowStatus(dts_Etn_File.getRowPosition()) === 0) {
            $c.en.fn_prodInfo_filedown(dts_Etn_File, dts_Etn_File.getCellData(row, "BZ_PROCS_NO"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08113.grd_Fil_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function() {
    try {
        let rtn = confirm('첨부파일을 추가 하시겠습니까?');
        if (rtn === 1) {
            if (dts_Etn_File.getRowCount() >= 30) {
                // 첨부파일 갯수 처리(30개)
                await $c.win.alert("첨부파일은 최대 30개 입니다.");
                return;
            }
            dts_Etn_File.insertRow();
            inf_find.open();
            if (inf_find.getValue() !== "") {
                if (scwin.notiId === "input") {
                    dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
                    file_name.setValue(inf_find.getValue());
                    await scwin.saveFile();
                } else {
                    dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
                    dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_SEQ", dts_Etn_File.getRowPosition());
                    dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "BZ_PROCS_NO", scwin.vBzProcsNo);
                    file_name.setValue(inf_find.getValue());
                    await scwin.updateFile();
                }
            } else {
                dts_Etn_File.removeRow(dts_Etn_File.getRowPosition());
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_linedelete_onclick = async function() {
    try {
        let rtn = confirm('첨부파일을 삭제 하시겠습니까?');
        if (rtn === 1) {
            // [확인] 버튼이 눌려졌을 경우
            dts_Etn_File.removeRow(dts_Etn_File.getRowPosition());
            if (dts_Etn_File.getRowCount() === 0) {
                await scwin.deleteFile();
            } else {
                scwin.vDelCheck = "Y";
                if (scwin.notiId === "input") {
                    await scwin.saveFile();
                } else {
                    await scwin.updateFile();
                }
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = dts_Etn_File.getCellData(dts_Etn_File.getRowPosition(), "filename");
        if (scwin.notiId === "input") {
            dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
            dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_SEQ", dts_Etn_File.getRowPosition());
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08113.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name trs_SaveAddFile_OnSuccess
 * @description Save Add File On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_SaveAddFile_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 등록"));
        $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.trs_SaveAddFile_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_SaveAddFile_OnFail
 * @description Save Add File On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_SaveAddFile_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 등록"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.trs_SaveAddFile_OnFail" });
    }
};

/**
 * @method
 * @name trs_UpdateAddFile_OnSuccess
 * @description Update Add File On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_UpdateAddFile_OnSuccess = async function() {
    try {
        if (scwin.vDelCheck === "N") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 수정"));
        } else {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 삭제"));
        }
        $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo);
        scwin.vDelCheck = "N";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.trs_UpdateAddFile_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_UpdateAddFile_OnFail
 * @description Update Add File On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_UpdateAddFile_OnFail = async function() {
    try {
        if (scwin.vDelCheck === "N") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 수정"));
        } else {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 삭제"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.trs_UpdateAddFile_OnFail" });
    }
};

/**
 * @method
 * @name trs_DeleteAddFile_OnSuccess
 * @description Delete Add File On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_DeleteAddFile_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 삭제"));
        scwin.vDelCheck = "N";
        $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.trs_DeleteAddFile_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_DeleteAddFile_OnFail
 * @description Delete Add File On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_DeleteAddFile_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 삭제"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08113.trs_DeleteAddFile_OnFail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    if (scwin.TR_JOB === 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    // alert('trsIdx:'+trsIdx);
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : trsIdx,
    //     BZ_PROCS_NO : scwin.vBzProcsNo
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/etn/EtnNewList.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/etn/EtnNewList.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveFile
 * @description save File 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveFile = async function() {
    let fileYn = "N";
    for (i = 1; i <= dts_Etn_File.getRowCount(); i++) {
        if (dts_Etn_File.getCellData(i, "ATTACH_FILE_NM") !== "") {
            fileYn = "Y";
        }
    }
    if (fileYn === "N") {
        await $c.win.alert("첨부파일을 하나이상 등록해주세요");
        return;
    }
    const sbmOptions = {
        id : "sbm_trs_SaveAddFile",
        action : "/etn/EtnNewList.do",
        ref : "dts_Etn_File",
        target : "trs_SaveAddFile=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name updateFile
 * @description update File 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.updateFile = async function() {
    if (dts_Etn_File.getRowCount() === 0) {
        await $c.win.alert("첨부파일을 한개이상  입력해주세요.");
        return;
    }
    const sbmOptions = {
        id : "sbm_trs_UpdateAddFile",
        action : "/etn/EtnNewList.do",
        ref : "dts_Etn_File",
        target : "trs_UpdateAddFile=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name deleteFile
 * @description delete File 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteFile = async function() {

    // dts_delEtnAddFile.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_delEtnAddFile.insertRow();
    dts_delEtnAddFile.setCellData(1, "bz_procs_no", scwin.vBzProcsNo);
    const sbmOptions = {
        id : "sbm_trs_DeleteAddFile",
        action : "/etn/EtnNewList.do",
        ref : "dts_delEtnAddFile",
        target : "trs_DeleteAddFile=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_ISU_CD_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
    }
};

/**
 * @method
 * @name initForm
 * @description init Form 처리
 * @param {*} gubnVal gubnVal
 * @returns {void}
 * @hidden N
 */
scwin.initForm = function(gubnVal) {

};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (edt_EXPS_RTO.getValue() === "") {
        await $c.win.alert("[제비용]를 입력하세요.");
        edt_EXPS_RTO.focus();
        return false;
    }
    if (txb_HPAGE.getValue() === "") {
        await $c.win.alert("[홈페이지]를 입력하세요.");
        txb_HPAGE.focus();
        return false;
    }
    if (txa_ETN_PROD_INFO.getValue() === "") {
        await $c.win.alert("[상품정보(기본정보)]를 입력하세요.");
        txa_ETN_PROD_INFO.focus();
        return false;
    }
    if (txa_ETN_INVSTWARN_CONTN.getValue() === "") {
        await $c.win.alert("[상품정보(투자유의사항)]를 입력하세요.");
        txa_ETN_INVSTWARN_CONTN.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setValue
 * @description set Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.setValue = function() {
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Item.setCellData(1, "EXPS_RTO", edt_EXPS_RTO.getValue());
    dts_Item.setCellData(1, "HPAGE", txb_HPAGE.getValue());
    dts_Item.setCellData(1, "ETN_PROD_INFO", txa_ETN_PROD_INFO.getValue());
    dts_Item.setCellData(1, "ETN_INVSTWARN_CONTN", txa_ETN_INVSTWARN_CONTN.getValue());
    dts_Item.setCellData(1, "DISTR_PAY_BAS_DD_ENG_CONTN", txa_DISTR_PAY_BAS_DD_ENG_CONTN.getValue());
    dts_Item.setCellData(1, "ETN_ENG_PROD_INFO", txa_ETN_ENG_PROD_INFO.getValue());
    dts_Item.setCellData(1, "ETN_ENG_INVSTWARN_CONTN", txa_ETN_ENG_INVSTWARN_CONTN.getValue());
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        // dts_Item.UserStatus(1) = TB_JOB_INSERT;
        dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};
